ALTER TABLE app_user ADD COLUMN panel_role VARCHAR(16) CHECK(panel_role IN ('ADMIN','OPERADOR','LEITURA'));
ALTER TABLE device ADD COLUMN friendly_name VARCHAR(120) NOT NULL DEFAULT '';
ALTER TABLE device ADD COLUMN responsible VARCHAR(120) NOT NULL DEFAULT '';
ALTER TABLE device ADD COLUMN city VARCHAR(120) NOT NULL DEFAULT '';
ALTER TABLE device ADD COLUMN notes VARCHAR(2000) NOT NULL DEFAULT '';
ALTER TABLE device ADD COLUMN windows_user VARCHAR(200);
ALTER TABLE device ADD COLUMN app_version VARCHAR(40);
ALTER TABLE device ADD COLUMN agent_version VARCHAR(80);
ALTER TABLE device ADD COLUMN internal_ip VARCHAR(200);
ALTER TABLE device ADD COLUMN public_ip VARCHAR(80);
ALTER TABLE device ADD COLUMN boot_at TIMESTAMP WITH TIME ZONE;
ALTER TABLE device ADD COLUMN uptime_seconds BIGINT;
ALTER TABLE device ADD COLUMN online_since TIMESTAMP WITH TIME ZONE;
ALTER TABLE device ADD COLUMN agent_health VARCHAR(24);
ALTER TABLE device ADD COLUMN metric_at TIMESTAMP WITH TIME ZONE;
ALTER TABLE device ADD COLUMN cpu_pct DOUBLE PRECISION;
ALTER TABLE device ADD COLUMN memory_pct DOUBLE PRECISION;
ALTER TABLE device ADD COLUMN disk_free_pct DOUBLE PRECISION;
ALTER TABLE device ADD COLUMN cpu_high_since TIMESTAMP WITH TIME ZONE;
ALTER TABLE device ADD COLUMN memory_high_since TIMESTAMP WITH TIME ZONE;
ALTER TABLE device ADD COLUMN disk_low_since TIMESTAMP WITH TIME ZONE;
ALTER TABLE device ADD COLUMN error_since TIMESTAMP WITH TIME ZONE;
CREATE INDEX device_presence_idx ON device(revoked,last_seen);
CREATE INDEX device_inventory_idx ON device(city,department,app_version);
CREATE TABLE device_change(id UUID PRIMARY KEY, device_id UUID NOT NULL REFERENCES device(id), admin_id UUID NOT NULL REFERENCES app_user(id), field_name VARCHAR(40) NOT NULL, old_value VARCHAR(2000), new_value VARCHAR(2000), reason VARCHAR(500), changed_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE INDEX device_change_history_idx ON device_change(device_id,changed_at);
CREATE TABLE device_metric(device_id UUID NOT NULL REFERENCES device(id), observed_at TIMESTAMP WITH TIME ZONE NOT NULL, cpu_pct DOUBLE PRECISION, memory_total BIGINT NOT NULL, memory_available BIGINT NOT NULL, memory_pct DOUBLE PRECISION NOT NULL, disk_free_pct DOUBLE PRECISION, disks VARCHAR(8192) NOT NULL, PRIMARY KEY(device_id,observed_at));
CREATE INDEX device_metric_retention_idx ON device_metric(observed_at);
CREATE TABLE device_metric_hour(device_id UUID NOT NULL REFERENCES device(id), hour_at TIMESTAMP WITH TIME ZONE NOT NULL, samples BIGINT NOT NULL, cpu_pct DOUBLE PRECISION, cpu_max DOUBLE PRECISION, memory_pct DOUBLE PRECISION, memory_total BIGINT, memory_available BIGINT, disk_free_pct DOUBLE PRECISION, disks VARCHAR(8192) NOT NULL, PRIMARY KEY(device_id,hour_at));
CREATE INDEX device_metric_hour_retention_idx ON device_metric_hour(hour_at);
CREATE TABLE device_event(id UUID PRIMARY KEY, device_id UUID NOT NULL REFERENCES device(id), event_code VARCHAR(40) NOT NULL, observed_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE INDEX device_event_history_idx ON device_event(device_id,observed_at);
CREATE TABLE monitoring_config(id INTEGER PRIMARY KEY CHECK(id=1), heartbeat_seconds INTEGER NOT NULL, metrics_seconds INTEGER NOT NULL, offline_seconds INTEGER NOT NULL, cpu_limit DOUBLE PRECISION NOT NULL, memory_limit DOUBLE PRECISION NOT NULL, disk_free_limit DOUBLE PRECISION NOT NULL, duration_seconds INTEGER NOT NULL, silent_seconds INTEGER NOT NULL, detail_days INTEGER NOT NULL, hourly_days INTEGER NOT NULL, event_days INTEGER NOT NULL, expected_app VARCHAR(40) NOT NULL, expected_agent VARCHAR(80) NOT NULL, rollup_until TIMESTAMP WITH TIME ZONE);
INSERT INTO monitoring_config VALUES(1,30,60,100,90,90,10,300,3600,2,90,365,'','',NULL);
CREATE TABLE fleet_metric(observed_at TIMESTAMP WITH TIME ZONE PRIMARY KEY,total BIGINT NOT NULL,online BIGINT NOT NULL,offline BIGINT NOT NULL,in_session BIGINT NOT NULL,cpu_pct DOUBLE PRECISION,memory_pct DOUBLE PRECISION);
